        QCOMPARE(c.profiles()[0].candidate,profiles[0].candidate); QCOMPARE(c.profiles()[1].active,profiles[1].active); QVERIFY(c.profiles()[1].candidate!=profiles[1].candidate); QVERIFY(!c.profiles()[0].updateError.isEmpty());
