        const auto prepared=store.prepare(p,"proxies: [{name: Leaf, type: direct}]\nproxy-groups: [{name: Test, type: select, proxies: [Leaf]}]\nrules: [\"MATCH,Test\"]\n",settings,19090,QString(64,'a')); QVERIFY(prepared.result.ok); QVERIFY(store.save(settings,{prepared.profile}).ok);
        AppController c(root.path(),true,nullptr,platform); QSignalSpy init(&c,&AppController::initialized),finished(&c,&AppController::operationFinished); c.initialize(); QTRY_COMPARE(init.size(),1); MainWindow window(&c); window.show(); window.setPage(1);
        window.findChild<QTableWidget*>("profilesTable")->selectRow(0); auto* policy=window.findChild<QToolButton*>("profilePolicyButton"); QVERIFY(policy&&policy->isEnabled()); policy->click(); auto* dialog=window.findChild<QDialog*>("profilePolicyDialog"); QVERIFY(dialog); auto* automatic=dialog->findChild<QCheckBox*>("profileAutoUpdate"); const auto output=qEnvironmentVariable("MLASH_UI_SCREENSHOTS"); if (!output.isEmpty()) { QCoreApplication::processEvents(); QVERIFY(dialog->grab().save(output+"/subscription-details.png")); } automatic->setChecked(true); dialog->findChild<QSpinBox*>("profileUpdateHours")->setValue(6); platform->failSeal=true; dialog->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Save)->click(); QTRY_COMPARE(finished.size(),1); QVERIFY(!finished.last()[0].toBool()); QVERIFY(dialog->isVisible()); QVERIFY(automatic->isChecked()); QVERIFY(!c.profiles()[0].autoUpdate); QVERIFY(!store.load().profiles[0].autoUpdate);
        platform->failSeal=false; dialog->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Save)->click(); QTRY_COMPARE(finished.size(),2); QVERIFY(finished.last()[0].toBool()); QVERIFY(c.profiles()[0].autoUpdate); QCOMPARE(c.profiles()[0].updateIntervalHours,6); QCOMPARE(platform->writes,0);
