    void childDraftAndPendingPreventSilentGuiRelease() {
        QTemporaryDir root; auto platform=std::make_shared<DepthPlatform>(); AppController c(root.path(),true,nullptr,platform); QSignalSpy init(&c,&AppController::initialized); c.initialize(); QTRY_COMPARE(init.size(),1); MainWindow window(&c); window.setTrayAvailable(true); window.show(); QSignalSpy release(&window,&MainWindow::guiReleaseRequested);
        bool dirty=true,pending=true; auto* editor=new QDialog(&window); editor->setWindowTitle("Draft fixture"); DialogDraftGuard::protect(editor,[&] { return dirty; },[&] { return pending; }); editor->show(); QVERIFY(DialogDraftGuard::hasDrafts(&window)); QVERIFY(!window.close()); QCOMPARE(release.size(),0); QVERIFY(!editor->close());
        pending=false; answer(QMessageBox::No); QVERIFY(!editor->close()); QVERIFY(editor->isVisible()); answer(QMessageBox::No); QVERIFY(!window.close()); QCOMPARE(release.size(),0); answer(QMessageBox::Yes); QVERIFY(window.close()); QCOMPARE(release.size(),1); QCOMPARE(platform->writes,0);
    }
